 body=zlib.decompress(base64.b64decode(''))
 if len(body)!=10466 or hashlib.sha256(body).hexdigest()!='23c630bd73abfe6a5f4862e9285856e4bd4bfcb74b7adec79d124ae2424fe22e':raise RuntimeError('EXACT_PREFLIGHT_TOOL_REQUIRED')
